#!/usr/bin/env python3
"""Review-time import of font facts when updating the pinned TCZ graph.

Usage: python3 tools/import-font-cache.py ROOT > font-cache.lock.json
ROOT must contain caches generated by the pinned guest Fontconfig 2.16.2.
Normal desktop builds use font_cache.py and do not run this maintenance tool.
"""
import hashlib
import json
from pathlib import Path
import struct
import sys

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
import font_cache


class Reader:
    def __init__(self, data):
        self.data = data
        if self.get(0, "IIq") != (0xFC02FC04, 9, len(data)):
            raise ValueError("expected a complete le64.cache-9")

    def get(self, offset, fmt):
        if offset < 0 or offset + struct.calcsize("<" + fmt) > len(self.data):
            raise ValueError("font cache offset out of bounds")
        return struct.unpack_from("<" + fmt, self.data, offset)

    def q(self, offset):
        return self.get(offset, "q")[0]

    def pointer(self, base, field):
        return base + (self.q(field) & ~1)

    def string(self, offset):
        if not 0 <= offset < len(self.data):
            raise ValueError("font cache string out of bounds")
        return self.data[offset:self.data.index(0, offset)].decode()

    def value(self, offset, kind):
        if kind in (1, 4):
            return self.get(offset + 8, "i")[0]
        if kind == 2:
            return self.get(offset + 8, "d")[0]
        target = self.pointer(offset, offset + 8)
        if kind == 3:
            return self.string(target)
        if kind == 6:
            count, = self.get(target + 4, "i")
            leaves, numbers = target + self.q(target + 8), target + self.q(target + 16)
            return [[self.get(numbers + index * 2, "H")[0],
                     list(self.get(leaves + self.q(leaves + index * 8), "8I"))]
                    for index in range(count)]
        if kind == 8:
            extra, count = self.get(target, "qI")
            if extra or count != 9:
                raise ValueError("unexpected pinned language map")
            return list(self.get(target + 12, "9I"))
        raise ValueError(f"unexpected pinned font value type: {kind}")

    def directory(self, intern):
        fonts = []
        font_set = self.q(40)
        pointers = self.pointer(font_set, font_set + 8)
        for index in range(self.get(font_set, "i")[0]):
            pattern = self.pointer(font_set, pointers + index * 8)
            elements = pattern + self.q(pattern + 8)
            records = []
            for index in range(self.get(pattern, "i")[0]):
                entry = elements + index * 16
                current = self.pointer(entry, entry + 8)
                values = []
                seen = set()
                while current:
                    if current in seen:
                        raise ValueError("cyclic font value list")
                    seen.add(current)
                    kind = self.get(current + 8, "i")[0]
                    binding = self.get(current + 24, "i")[0]
                    values.append([kind, binding, intern(kind, self.value(current + 8, kind))])
                    current = self.pointer(current, current) if self.q(current) else 0
                records.append([self.get(entry, "i")[0], values])
            fonts.append(records)
        children = self.q(24)
        return dict(path=self.string(self.q(16)),
                    subdirs=[self.string(children + self.q(children + index * 8))
                             for index in range(self.get(32, "i")[0])], fonts=fonts)


def import_facts(root):
    values, offsets, directories, hashes = [], {}, [], {}
    def intern(kind, value):
        key = json.dumps([kind, value], sort_keys=True)
        if key not in offsets:
            offsets[key] = len(values)
            values.append(value)
        return offsets[key]
    for path in sorted((root / "var/cache/fontconfig").glob("*-le64.cache-9")):
        data = path.read_bytes()
        directories.append(Reader(data).directory(intern))
        hashes[path.name] = hashlib.sha256(data).hexdigest()
    if not directories:
        raise ValueError("no pinned guest caches to import")
    return dict(format="fontconfig-le64-cache-9", fontconfig_version="2.16.2",
                fontconfig_package_sha256="470f3ad3b7a44d979177e4770264cc64e570a70db619d981e2d0c53389f700fe",
                input_sha256=font_cache.fingerprint(root), source_cache_sha256=hashes,
                values=values, directories=directories)


if __name__ == "__main__":
    print(json.dumps(import_facts(Path(sys.argv[1])), ensure_ascii=True, separators=(",", ":")))
